import { useState } from 'react';
import { ImageGallery } from './ImageGallery';
import { ProductInfo } from './ProductInfo';
import { RelatedProducts } from './RelatedProducts';

export function ProductPage() {
  const [cartCount, setCartCount] = useState(0);

  return (
    <div className="min-h-screen bg-white font-sans">
      {/* Nav */}
      <nav className="border-b border-slate-100 px-6 py-4 flex items-center justify-between">
        <span className="font-bold text-slate-800 text-lg">Shoppe</span>
        <div className="flex items-center gap-4 text-sm text-slate-500">
          <a href="#" className="hover:text-slate-800">Shop</a>
          <a href="#" className="hover:text-slate-800">About</a>
          <button className="relative">
            🛒
            {cartCount > 0 && (
              <span className="absolute -top-1.5 -right-1.5 w-4 h-4 bg-violet-600 text-white rounded-full text-[10px] flex items-center justify-center font-bold">{cartCount}</span>
            )}
          </button>
        </div>
      </nav>

      <main className="max-w-6xl mx-auto px-4 py-10">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
          <ImageGallery />
          <ProductInfo onAddToCart={() => setCartCount(c => c + 1)} />
        </div>
        <RelatedProducts />
      </main>
    </div>
