import { useState } from 'react';

const COLORS = [
  'from-violet-400 to-fuchsia-400',
  'from-sky-400 to-blue-500',
  'from-emerald-400 to-teal-500',
  'from-orange-400 to-rose-400',
];

export function ImageGallery() {
  const [active, setActive] = useState(0);

  return (
    <div className="space-y-3">
      {/* Main image */}
      <div className={`aspect-square rounded-2xl bg-gradient-to-br ${COLORS[active]} flex items-center justify-center shadow-lg`}>
        <span className="text-6xl">👟</span>
      </div>
      {/* Thumbnails */}
      <div className="grid grid-cols-4 gap-2">
        {COLORS.map((c, i) => (
          <button
            key={i}
            onClick={() => setActive(i)}
            className={`aspect-square rounded-xl bg-gradient-to-br ${c} flex items-center justify-center transition-all ${
              active === i ? 'ring-2 ring-violet-600 ring-offset-2 scale-95' : 'opacity-60 hover:opacity-80'
            }`}
            aria-label={`View image ${i + 1}`}
          >
            <span className="text-xl">👟</span>
          </button>
        ))}
      </div>
    </div>
  );
}

/components/ProductInfo.tsx.content:
import { useState } from 'react';
import { ShoppingBag, Heart, Star } from 'lucide-react';

const SIZES = ['US 6', 'US 7', 'US 8', 'US 9', 'US 10', 'US 11'];
const COLORS = [
  { name: 'Violet',   cls: 'bg-violet-500' },
  { name: 'Sky',      cls: 'bg-sky-400' },
  { name: 'Emerald',  cls: 'bg-emerald-500' },
  { name: 'Rose',     cls: 'bg-rose-500' },
];

interface ProductInfoProps {
  onAddToCart: () => void;
}

export function ProductInfo({ onAddToCart }: ProductInfoProps) {
  const [selectedSize, setSelectedSize] = useState<string | null>(null);
  const [selectedColor, setSelectedColor] = useState(0);
  const [wishlist, setWishlist] = useState(false);
  const [qty, setQty] = useState(1);
  const [added, setAdded] = useState(false);

  const handleAdd = () => {
    if (!selectedSize) return;
    onAddToCart();
    setAdded(true);
    setTimeout(() => setAdded(false), 1800);
  };

  return (
    <div className="flex flex-col">
      {/* Rating */}
      <div className="flex items-center gap-1 mb-3">
        {[...Array(5)].map((_, i) => (
          <Star key={i} className={`h-4 w-4 ${i < 4 ? 'text-amber-400 fill-amber-400' : 'text-slate-300'}`} />
        ))}
        <span className="text-sm text-slate-500 ml-1">4.0 (128 reviews)</span>
      </div>

      <h1 className="text-3xl font-bold text-slate-800 mb-1">AeroRun Pro X9</h1>
      <p className="text-slate-500 text-sm mb-4">Lightweight performance running shoe with reactive foam midsole.</p>

      <div className="flex items-baseline gap-3 mb-6">
        <span className="text-3xl font-bold text-slate-800">$129</span>
        <span className="text-slate-400 line-through text-sm">$179</span>
        <span className="text-xs font-semibold bg-rose-100 text-rose-600 px-2 py-0.5 rounded-full">-28%</span>
      </div>

      {/* Color */}
      <div className="mb-5">
        <p className="text-xs font-medium text-slate-600 mb-2">Color — <span className="text-slate-800">{COLORS[selectedColor].name}</span></p>
        <div className="flex gap-2">
          {COLORS.map((c, i) => (
            <button
              key={i}
              onClick={() => setSelectedColor(i)}
              className={`w-8 h-8 rounded-full ${c.cls} transition-all ${
                selectedColor === i ? 'ring-2 ring-offset-2 ring-violet-600 scale-110' : 'opacity-70 hover:opacity-100'
              }`}
              aria-label={`Color: ${c.name}`}
            />
          ))}
        </div>
      </div>

      {/* Size */}
      <div className="mb-6">
        <p className="text-xs font-medium text-slate-600 mb-2">Size</p>
        <div className="flex flex-wrap gap-2">
          {SIZES.map(s => (
            <button
              key={s}
              onClick={() => setSelectedSize(s)}
              className={`h-9 px-3 rounded-lg text-sm font-medium border transition-all ${
                selectedSize === s
                  ? 'border-violet-600 bg-violet-50 text-violet-700'
                  : 'border-slate-200 text-slate-600 hover:border-slate-300'
              }`}
            >
              {s}
            </button>
          ))}
        </div>
        {!selectedSize && <p className="text-xs text-slate-400 mt-1">Please select a size</p>}
      </div>

      {/* Qty + CTA */}
      <div className="flex items-center gap-3">
        <div className="flex items-center border border-slate-200 rounded-lg overflow-hidden">
          <button onClick={() => setQty(q => Math.max(1, q - 1))} className="px-3 py-2 text-slate-500 hover:bg-slate-50 transition-colors">−</button>
          <span className="px-4 text-sm font-medium text-slate-800">{qty}</span>
          <button onClick={() => setQty(q => q + 1)} className="px-3 py-2 text-slate-500 hover:bg-slate-50 transition-colors">+</button>
        </div>

        <button
          onClick={handleAdd}
          disabled={!selectedSize}
          className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl font-semibold text-sm transition-all ${
            added
              ? 'bg-emerald-500 text-white'
              : selectedSize
              ? 'bg-violet-600 hover:bg-violet-500 text-white'
              : 'bg-slate-100 text-slate-400 cursor-not-allowed'
          }`}
        >
          <ShoppingBag className="h-4 w-4" />
          {added ? 'Added!' : 'Add to cart'}
        </button>

        <button
          onClick={() => setWishlist(w => !w)}
          className={`p-2.5 rounded-xl border transition-all ${
            wishlist ? 'border-rose-400 bg-rose-50 text-rose-500' : 'border-slate-200 text-slate-400 hover:border-slate-300'
          }`}
          aria-label="Add to wishlist"
        >
          <Heart className={`h-4 w-4 ${wishlist ? 'fill-rose-500' : ''}`} />
        </button>
      </div>
    </div>
  );
}

