const related = [
  { name: 'CloudStep 5', price: '$89',  badge: 'Sale', color: 'from-sky-400 to-blue-500' },
  { name: 'TerraMax GT', price: '$149', badge: 'New',  color: 'from-emerald-400 to-teal-500' },
  { name: 'FlexRun Air', price: '$109', badge: null,   color: 'from-orange-400 to-rose-400' },
  { name: 'SprintElite', price: '$199', badge: 'Hot',  color: 'from-violet-400 to-fuchsia-400' },
];

export function RelatedProducts() {
  return (
    <section className="mt-16">
      <h2 className="text-xl font-bold text-slate-800 mb-5">You may also like</h2>
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {related.map(p => (
          <button key={p.name} className="group text-left bg-white rounded-2xl border border-slate-100 shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all overflow-hidden">
            <div className={`aspect-square bg-gradient-to-br ${p.color} flex items-center justify-center relative`}>
              <span className="text-3xl">👟</span>
              {p.badge && (
                <span className="absolute top-2 left-2 text-[10px] font-bold bg-white/90 text-slate-700 px-1.5 py-0.5 rounded-full">{p.badge}</span>
              )}
            </div>
            <div className="p-3">
              <p className="text-sm font-semibold text-slate-800 group-hover:text-violet-700 transition-colors">{p.name}</p>
              <p className="text-sm font-bold text-slate-700 mt-0.5">{p.price}</p>
            </div>
          </button>
        ))}
      </div>
    </section>
  );
}
